class TestKemRoundTrip:
    """Validates the full encaps/decaps cycle with shared-secret equality."""

    def test_round_trip_shared_secret(self, valid_keypair, valid_ciphertext):
        """Decapsulating a valid ciphertext must recover the original secret."""
        pk, sk = valid_keypair
        ct, ss_enc = valid_ciphertext
        ss_dec = qkd_ffi.KyberSharedSecret()
        result = qkd_ffi._qkd_lib.kem_decaps(
            ctypes.byref(ss_dec), ctypes.byref(ct), ctypes.byref(sk)
        )
        assert result == 0
        assert bytes(ss_enc) == bytes(ss_dec)

    def test_round_trip_multiple(self, valid_keypair):
        """Multiple encaps/decaps cycles must all succeed."""
        pk, sk = valid_keypair
        for _ in range(10):
            ct = qkd_ffi.KyberCiphertext()
            ss_enc = qkd_ffi.KyberSharedSecret()
            qkd_ffi._qkd_lib.kem_encaps(
                ctypes.byref(ct), ctypes.byref(ss_enc), ctypes.byref(pk)
            )
            ss_dec = qkd_ffi.KyberSharedSecret()
            qkd_ffi._qkd_lib.kem_decaps(
                ctypes.byref(ss_dec), ctypes.byref(ct), ctypes.byref(sk)
            )
            assert bytes(ss_enc) == bytes(ss_dec)

    def test_decaps_with_wrong_key_fails(self, valid_keypair, valid_ciphertext):
        """Decapsulation with a mismatched private key must fail."""
        pk2, sk2 = qkd_ffi.KyberPublicKey(), qkd_ffi.KyberPrivateKey()
        qkd_ffi._qkd_lib.kem_keypair(ctypes.byref(pk2), ctypes.byref(sk2))
        ct, _ = valid_ciphertext
        ss_dec = qkd_ffi.KyberSharedSecret()
        result = qkd_ffi._qkd_lib.kem_decaps(
            ctypes.byref(ss_dec), ctypes.byref(ct), ctypes.byref(sk2)
        )
        # Kyber decapsulation is implicit-reject; it returns 0 but a different secret
        assert result == 0
        # The shared secret must NOT match the original
        _, ss_orig = valid_ciphertext
        assert bytes(ss_dec) != bytes(ss_orig)

    def test_corrupted_ciphertext_fails(self, valid_keypair, valid_ciphertext):
        """A single-bit flip in the ciphertext must produce a different secret."""
        pk, sk = valid_keypair
        ct, ss_orig = valid_ciphertext
        # Flip one byte in the ciphertext
        corrupted = bytearray(bytes(ct))
        corrupted[0] ^= 0x01
        ct_corrupt = qkd_ffi.KyberCiphertext()
        ctypes.memmove(ctypes.byref(ct_corrupt), bytes(corrupted), len(corrupted))
        ss_dec = qkd_ffi.KyberSharedSecret()
        qkd_ffi._qkd_lib.kem_decaps(
            ctypes.byref(ss_dec), ctypes.byref(ct_corrupt), ctypes.byref(sk)
        )
        assert bytes(ss_dec) != bytes(ss_orig)


