class TestPropertyBased:
    """Fuzz-style validation of the FFI layer using Hypothesis."""

    @given(st.binary(min_size=1, max_size=64))
    def test_shared_secret_is_32_bytes(self, _):
        """Every generated shared secret must be exactly 32 bytes."""
        pk, sk = qkd_ffi.KyberPublicKey(), qkd_ffi.KyberPrivateKey()
        qkd_ffi._qkd_lib.kem_keypair(ctypes.byref(pk), ctypes.byref(sk))
